function chemistrySprite(c,id,time=0){if(id===32){for(let [x,y,w,h]of [[12,24,22,24],[28,10,24,32],[25,30,29,22],[7,35,20,16]]){poly(c,[[x,y+4],[x+5,y],[x+w-6,y],[x+w,y+8],[x+w-2,y+h-4],[x+6,y+h],[x,y+h-7]],'#423b3b');poly(c,[[x+2,y+5],[x+7,y+2],[x+w-7,y+2],[x+w-3,y+9],[x+w-6,y+14],[x+5,y+12]],'#8b7970');c.fillStyle='#c4c0b2';c.fillRect(x+6,y+3,6,2);c.fillStyle='#794f43';c.fillRect(x+5,y+h-6,8,3)}return}if(id===35){for(let [x,y]of [[9,22],[23,7],[35,19]]){poly(c,[[x,y+5],[x+14,y],[x+20,y+25],[x+6,y+31]],'#87958e');poly(c,[[x+1,y+5],[x+13,y+1],[x+18,y+24],[x+6,y+29]],'#d8e2da');for(let k=0;k<4;k++){c.fillStyle=k%2?'#b0c2b9':'#f3f6e9';c.fillRect(x+4+k*3,y+7,1,17)}}return}if(id===36){poly(c,[[7,20],[45,15],[56,22],[56,43],[17,49],[7,42]],'#a7b3a1');poly(c,[[8,20],[45,16],[55,22],[17,28]],'#e3e4d2');poly(c,[[17,28],[55,22],[55,42],[17,48]],'#c9cebc');return}poly(c,[[25,9],[39,9],[39,14],[37,14],[37,25],[54,47],[51,53],[13,53],[10,47],[27,25],[27,14],[25,14]],'#a4bdb5');poly(c,[[29,14],[35,14],[35,26],[50,47],[48,50],[16,50],[14,47],[29,26]],'#18392f');poly(c,[[23,35],[41,35],[49,47],[47,49],[17,49],[15,47]],id===33?'#c6c197':'#9bb8ac');c.fillStyle='#e5eee0';c.fillRect(29,15,2,12);c.fillRect(17,43,2,5);c.fillRect(25,9,14,3);if(id===34)for(let k=0;k<3;k++){let y=7-k*4; c.fillStyle='#d0e2d099';c.fillRect(29+Math.round(Math.sin(time*3+k)*2),y,1,3)}}
