function plank(c){for(let i=0;i<3;i++){poly(c,[[8,18+i*10],[48,13+i*10],[56,18+i*10],[16,25+i*10]],'#b79565');poly(c,[[16,25+i*10],[56,18+i*10],[56,23+i*10],[16,30+i*10]],'#816240');c.fillStyle='#d6b77c';c.fillRect(20,20+i*10,23,1)}}
function buildingMaterial(c,id){if(id===26){matrix(c);for(let [x,y,k] of [[16,20,1],[31,13,.9],[40,30,.7]]){poly(c,[[x,y],[x+12*k,y-7*k],[x+19*k,y+8*k],[x+7*k,y+15*k]],'#ca8295');poly(c,[[x,y],[x+12*k,y-7*k],[x+9*k,y+4*k],[x+3*k,y+7*k]],'#f1b2ba');poly(c,[[x+7*k,y+15*k],[x+19*k,y+8*k],[x+15*k,y+20*k]],'#925e76')}return}if(id===28){for(let y of [18,35]){poly(c,[[8,y],[48,y-8],[57,y-3],[17,y+6]],'#aab8b0');poly(c,[[17,y+6],[57,y-3],[57,y+4],[17,y+13]],'#667a73')}return}if(id===30||id===29){for(let i=0;i<12;i++){let x=8+i*19%44,y=29+i*13%20;poly(c,[[x,y],[x+5,y-5],[x+11,y],[x+7,y+7]],id===29?'#d9d9bf':i%2?'#7e8a78':'#9ca28c')}return}poly(c,[[10,22],[43,16],[55,25],[22,33]],id===31?'#acb7a4':'#b0a4a5');poly(c,[[10,22],[22,33],[22,49],[10,39]],id===31?'#6e8173':'#756d76');poly(c,[[22,33],[55,25],[55,42],[22,49]],id===31?'#879887':'#93898d');}
function poly(c,points,color){c.fillStyle=color;c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fill()}
function irisAgate(c,phase=0){const patches=['#b5dbd5','#95b6e2','#d3a4d5','#e3bf92','#b3cba4','#d6c7e8','#83c8c4','#d9adac'];
for(let y=5;y<47;y++)for(let x=6;x<57;x++){let dx=(x-31)/24,dy=(y-26)/20,theta=Math.atan2(dy,dx),r=Math.hypot(dx,dy),edge=1+.038*Math.sin(theta*7)+.045*Math.sin(theta*11+.5),hole=Math.hypot((x-32)/4.2,(y-27)/5.4);if(r>edge||hole<1)continue;let color;if(edge-r<.075)color=y>28?'#8e6a3f':'#c5a16a';else if(edge-r<.16)color=['#d1ad79','#c4a878','#dfc39b'][Math.abs(x+y)%3];else if(hole<1.3)color='#716450';else{let a=Math.sin(x*.15+Math.sin(y*.19)*1.9),b=Math.cos(y*.22+Math.sin(x*.16)*1.6);color=patches[Math.floor((a+b+2)*1.75)%patches.length];if((Math.sin(x*.55+y*.36)+Math.cos(x*.21-y*.47))>1.5)color='#ece3d0';}if(r<.8&&hole>1.3&&color!=='#ece3d0'){let a=Math.sin(x*.15+Math.sin(y*.19)*1.9),b=Math.cos(y*.22+Math.sin(x*.16)*1.6),patch=Math.floor((a+b+2)*1.75);color=`hsl(${(phase*360+patch*47)%360} 48% ${65+Math.sin(patch+phase*6)*9}%)`;}if(r<.82&&hole>1.3&&Math.sin(phase*Math.PI*2*2+x*.045+y*.025)>.965)color='#f6ffe5';c.fillStyle=color;c.fillRect(x,y,1,1)}
for(let i=0;i<19;i++){let x=12+i*2,y=13+Math.round(Math.sin(i*.4)*2);if(i<9){c.fillStyle='#f3e3bf99';c.fillRect(x,y,1,1)}}}
function matrix(c){poly(c,[[7,43],[16,38],[42,38],[56,44],[53,51],[39,54],[13,52],[5,48]],'#544738');poly(c,[[7,43],[16,38],[42,38],[56,44],[35,48],[13,47]],'#8c6d51');poly(c,[[5,48],[13,47],[35,48],[39,54],[13,52]],'#6e5542');c.fillStyle='#b1936f';c.fillRect(12,43,6,2);c.fillRect(43,45,5,2)}
function prism(c,x,y,w,h,lean){let bottom=y+h,mid=x+w/2,tip=mid+lean;poly(c,[[mid,y+8],[x,y+14],[x,bottom-4],[mid,bottom]],'#684392');poly(c,[[mid,y+8],[x+w,y+14],[x+w,bottom-4],[mid,bottom]],'#9a69ce');poly(c,[[tip,y],[x,y+14],[mid,y+8]],'#d2b6f4');poly(c,[[tip,y],[mid,y+8],[x+w,y+14]],'#a787de');poly(c,[[mid,y+8],[mid+2,y+10],[mid+2,bottom-2],[mid,bottom]],'#e4caff');c.fillStyle='#ecd8ff';c.fillRect(tip,y+2,1,3);c.fillStyle='#b78ae6';c.fillRect(x+2,y+17,1,Math.max(3,h-24));}
function amethyst(c){matrix(c);prism(c,10,18,13,29,-3);prism(c,38,15,13,32,3);prism(c,23,2,16,45,-1);c.fillStyle='#e7d7ff';c.fillRect(31,13,1,10)}
function cube(c,x,y,s){let h=s,half=s/2;poly(c,[[x,y],[x+s,y+half],[x,y+s],[x-s,y+half]],'#f1d984');poly(c,[[x-s,y+half],[x,y+s],[x,y+s+h],[x-s,y+half+h]],'#ac873f');poly(c,[[x,y+s],[x+s,y+half],[x+s,y+half+h],[x,y+s+h]],'#d4b75f');poly(c,[[x-s,y+half],[x-s+1,y+half],[x+1,y+s],[x+1,y+s+h],[x,y+s+h],[x,y+s]],'#f3da88');c.strokeStyle='#83682e';c.lineWidth=1;for(let i=3;i<s-1;i+=3){c.beginPath();c.moveTo(x+2,y+s+i);c.lineTo(x+s-1,y+half+i);c.stroke()}c.fillStyle='#fff0b4';c.fillRect(x-1,y+1,2,1)}
function pyrite(c){poly(c,[[5,44],[14,36],[43,36],[57,44],[54,51],[34,55],[9,52]],'#554f42');poly(c,[[5,44],[14,36],[43,36],[57,44],[30,49]],'#8a8170');c.fillStyle='#b5a68b';c.fillRect(11,44,5,2);c.fillRect(42,47,7,2);cube(c,17,26,10);cube(c,45,25,9);cube(c,30,9,13);cube(c,35,35,8)}
function obsidian(c){const outline=[[7,41],[13,17],[29,5],[47,12],[58,31],[49,49],[28,53],[10,47]];poly(c,outline,'#12151f');poly(c,[[13,17],[29,5],[47,12],[35,27],[7,41]],'#303342');poly(c,[[35,27],[47,12],[58,31],[49,49]],'#1c202c');poly(c,[[7,41],[35,27],[49,49],[28,53],[10,47]],'#20242d');c.save();c.beginPath();outline.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.clip();for(let i=0;i<4;i++){c.strokeStyle=['#78858e','#4c5967','#69737c','#374552'][i];c.lineWidth=1;c.beginPath();c.ellipse(17+i*3,33+i*2,12+i*5,5+i*3,-.45,.05,Math.PI*1.2);c.stroke()}c.restore();poly(c,[[14,18],[28,8],[32,9],[18,20]],'#a4aab0');c.fillStyle='#d4d1cb';c.fillRect(23,12,3,1);c.fillStyle='#59616b';c.fillRect(48,27,1,7)}
function orpiment(c){matrix(c);for(let [x,y,w,h]of [[10,21,11,25],[18,9,13,37],[34,5,12,42],[43,22,12,24],[27,20,12,29]]){poly(c,[[x,y+6],[x+w-3,y],[x+w,y+h-3],[x+3,y+h]],'#b9651f');poly(c,[[x,y+6],[x+4,y+4],[x+6,y+h-1],[x+3,y+h]],'#e59b27');poly(c,[[x+4,y+4],[x+w-3,y],[x+w,y+h-3],[x+6,y+h-1]],'#ed8b22');c.fillStyle='#f9c83b';c.fillRect(x+5,y+8,3,7);c.fillRect(x+7,y+h-13,2,6);c.fillStyle='#ffe376';c.fillRect(x+4,y+5,2,2)}}
function agate(c){const tones=['#eeeee4','#b5b9b5','#f8f6eb','#d1d4cd','#f1eee1','#aeb4b1','#e5e7de'];for(let y=5;y<49;y++)for(let x=6;x<58;x++){let dx=(x-31)/25,dy=(y-27)/21,t=Math.atan2(dy,dx),r=Math.hypot(dx,dy),edge=1+.045*Math.sin(t*7)+.025*Math.cos(t*13);if(r>edge)continue;let warped=r+.045*Math.sin(t*3+r*3)+.025*Math.cos(t*5-r*4)+.012*Math.sin(t*9),band=warped<.15?0:warped<.29?1:warped<.44?2:warped<.57?3:warped<.72?4:warped<.84?5:6;c.fillStyle=r>edge-.075?'#b7a68b':tones[band];c.fillRect(x,y,1,1)}}
function peridot(c){poly(c,[[5,32],[10,22],[22,16],[37,15],[50,20],[59,32],[55,44],[44,52],[26,54],[12,48]],'#565a53');poly(c,[[5,32],[10,22],[22,16],[37,15],[50,20],[59,32],[43,43],[20,45]],'#929387');poly(c,[[10,32],[18,23],[36,20],[48,27],[43,38],[25,43]],'#a6a397');for(let i=0;i<17;i++){let x=12+(i*17)%40,y=24+(i*11)%21;c.fillStyle=i%2?'#64685e':'#b4b0a0';c.fillRect(x,y,3,2)}for(let [x,y,w,h]of [[12,28,9,10],[23,21,10,12],[38,24,11,9],[31,36,8,11],[46,36,7,8],[17,41,8,8]]){poly(c,[[x,y+3],[x+w*.6,y],[x+w,y+4],[x+w-2,y+h],[x+2,y+h-1]],'#52612c');poly(c,[[x,y+3],[x+w*.6,y],[x+w-2,y+h-3],[x+2,y+h-1]],'#94a74e');poly(c,[[x+2,y+3],[x+w*.6,y],[x+4,y+h-4]],'#c3ce80');poly(c,[[x+w*.6,y],[x+w,y+4],[x+w-2,y+h],[x+w-4,y+5]],'#6e8335');c.fillStyle='#e1e3ad';c.fillRect(x+3,y+3,2,1)}}
