function stoneMaterial(c,x,y,kind,noise,angle=0,offset=0){if([7,8,9,10].includes(kind)){c.save();if(kind!==8){let colors={7:['#a97148','#ac744b'],9:['#9f6745','#a26b48'],10:['#90563e','#955b41']}[kind];c.fillStyle=colors[noise>.55?1:0];c.fillRect(x,y,20,20);c.fillStyle=kind===7?'#d4935d33':kind===9?'#c38a5730':'#b1754b30';c.fillRect(x+2,y+2,15,2);c.fillStyle='#79513566';c.fillRect(x,y+19,20,1);c.fillRect(x+19,y,1,20)}else{c.fillStyle=noise>.48?'#794333':'#704034';c.fillRect(x,y,20,20);poly(c,[[x+1,y+3],[x+10,y+1],[x+18,y+7],[x+13,y+14],[x+4,y+16]],'#91523b');c.strokeStyle='#422c27';c.lineWidth=1;c.beginPath();c.moveTo(x+2,y+5);c.lineTo(x+8,y+8);c.lineTo(x+6,y+14);c.lineTo(x+11,y+19);c.moveTo(x+8,y+8);c.lineTo(x+15,y+5);c.lineTo(x+19,y+8);c.stroke();c.fillStyle='#b0714b';c.fillRect(x+11,y+3,4,1)}c.restore();return}let palette={1:['#8d9f92','#a3afa0'],2:['#a5ad99','#b7b29a'],3:['#617b69','#738775'],5:['#405d4c','#506958'],6:['#314b3e','#3b5446']}[kind]||['#314b3e','#3b5446'];c.fillStyle=palette[noise>.62?1:0];c.fillRect(x,y,20,20);c.fillStyle='#1b332944';c.fillRect(x,y+18,20,2);c.fillRect(x+18,y,2,20);if(kind===1||kind===2){c.fillStyle=kind===1?'#bdc8b277':'#d4cfa477';poly(c,[[x+3,y+4],[x+9,y+2],[x+14,y+6],[x+9,y+8],[x+4,y+7]],c.fillStyle);c.fillStyle=kind===1?'#637b6b':'#7d8974';c.fillRect(x+6,y+12,6,1);c.fillRect(x+11,y+9,1,4);if(noise>.76){c.fillStyle='#d2ccaa';c.fillRect(x+4,y+11,3,2)}}else{c.fillStyle='#a4b29b18';c.fillRect(x+3+(noise*6|0),y+6,5,2)}}
