specimenScience[44]={"formula": "CuFeS₂", "hardness": "3.5–4", "system": "四方晶系 / Tetragonal", "category": ["矿物", "Mineral"], "identity": ["铜铁硫化物，黄铜黄色、金属光泽；表面可有彩虹锖色，不是黄铁矿或自然金。", "A copper–iron sulfide with a brass-yellow metallic luster; surfaces may tarnish iridescently. Distinct from pyrite and native gold."], "genesis": ["常见于热液脉、网脉、浸染及交代矿床；也见于基性岩离溶和沉积环境。", "Common in hydrothermal veins, stockworks, disseminations and replacement deposits; also mafic-rock exsolution and sedimentary settings."], "sources": [["Handbook of Mineralogy", "https://www.handbookofmineralogy.org/pdfs/chalcopyrite.pdf"]]};
specimenScience[45]={formula:"Cu（主要组分） / Cu (main constituent)",category:["加工材料","Processed material"],identity:["游戏中的冶炼铜材，不代表天然自然铜标本。","Smelted copper material in the game, not a specimen of native copper."],sources:[]};
specimenScience[48]={formula:'黏土矿物＋铁氧化物混合物 / Clay minerals + iron oxides',category:['岩石／沉积物','Rock / sediment'],identity:['细粒混合物；橙色来自含铁组分，不具有唯一化学式。','A fine-grained mixture with an iron-bearing orange pigment, not a single mineral species.'],genesis:['硫化矿体风化氧化后可形成富铁残积物及黏土；游戏以橙色黏土表示。','Weathering of sulfide deposits can produce iron-rich residual material and clay; represented here by orange clay.'],sources:[]};
specimenScience[49]={formula:'Ca₅(PO₄)₃(F,Cl,OH)',hardness:'5',system:'通常为六方晶系 / Usually hexagonal',category:['矿物族通称','Mineral-group name'],identity:['磷灰石是含钙磷酸盐矿物的族称；图中黄色晶体以氟磷灰石形态为参考。','Apatite is a group name for calcium phosphates; the yellow crystal design refers to fluorapatite.'],genesis:['常见于火成岩副矿物、伟晶岩、热液脉和变质岩，也见于沉积磷块岩；部分可残留富集于风化壳。游戏中的氧化带分布不代表唯一成因。','Occurs as an accessory in igneous rocks, in pegmatites, hydrothermal veins, metamorphic rocks and sedimentary phosphorites; it may persist in weathering residues. The game distribution is not its only origin.'],sources:[['Handbook of Mineralogy — Fluorapatite','https://handbookofmineralogy.org/pdfs/fluorapatite.pdf']]};
specimenScience[50]={formula:'PbMoO₄',hardness:'2.75–3',system:'四方晶系 / Tetragonal',category:['矿物','Mineral'],identity:['钼酸铅矿物，常呈橙黄至橙红色的方形板状晶体，具树脂至金刚光泽。','Lead molybdate, commonly forming yellow-orange to red-orange square tabular crystals with resinous to adamantine luster.'],genesis:['热液铅矿床氧化带中的次生矿物；可与铅的碳酸盐、硫酸盐及铁锰氧化物共生。','A secondary mineral in oxidized hydrothermal lead deposits, associated with lead carbonates, sulfates and iron–manganese oxides.'],sources:[['Handbook of Mineralogy — Wulfenite','https://handbookofmineralogy.org/pdfs/wulfenite.pdf']]};
specimenScience[51]={formula:'(Zn,Cu)₂(AsO₄)(OH)',hardness:'3.5',system:'斜方晶系 / Orthorhombic',category:['矿物变种','Mineral variety'],identity:['含铜水砷锌石（Cuprian adamite），铜部分替代锌；不是独立矿物种，也不等同于锌橄榄铜矿（Zincolivenite）。','Copper-bearing adamite, with some Zn replaced by Cu; a variety rather than a separate mineral species, and distinct from zincolivenite.'],genesis:['含砷铅锌矿床氧化带中可形成水砷锌石；含铜变种需要铜参与。市售部分同名标本实际属于锌橄榄铜矿。','Adamite occurs in oxidized arsenic-bearing lead–zinc deposits; the cuprian variety also incorporates copper. Some specimens sold under this name are actually zincolivenite.'],sources:[['Mindat — Copper-bearing Adamite','https://www.mindat.org/min-1174.html']]};
for(const [id,data] of Object.entries(specimenScience)){const m=catalog[+id];m.science=data;}
